16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "initials", expression = "java(OwnerMapper.initials(owner))")
23	    @Mapping(target = "membershipNumber", ignore = true)
24	    @Mapping(target = "customerCode", ignore = true)
25	    @Mapping(target = "membershipTier", ignore = true)
26	    @Mapping(target = "namesakeCount", ignore = true)
27	    @Mapping(target = "sharesHousehold", ignore = true)
28	    @Mapping(target = "locality", ignore = true)
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    /** First letters of first and last name, upper-cased and dot-separated with a trailing dot, e.g. "J.S.". */
32	    static String initials(Owner owner) {
33	        return (owner.getFirstName().substring(0, 1) + "." + owner.getLastName().substring(0, 1) + ".")
34	                .toUpperCase();
35	    }
36	
37	    /**
38	     * The sequential membership number for the owner: one more than the number of owners that existed
39	     * before this one. Computed as the count of owners whose id is not greater than this owner's id.
40	     * Because a newly created owner always has the largest id, this equals the total owner count at
41	     * registration and stays stable when read back later.
42	     */
43	    static Integer membershipNumber(Owner owner, Collection<Owner> allOwners) {
44	        Integer id = owner.getId();
45	        if (id == null) {
46	            return null;
