package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "initials", expression = "java(OwnerMapper.initials(owner))")
    @Mapping(target = "membershipNumber", ignore = true)
    @Mapping(target = "customerCode", ignore = true)
    @Mapping(target = "membershipTier", ignore = true)
    @Mapping(target = "namesakeCount", ignore = true)
    @Mapping(target = "sharesHousehold", ignore = true)
    @Mapping(target = "locality", ignore = true)
    OwnerDto toOwnerDto(Owner owner);

    /** First letters of first and last name, upper-cased and dot-separated with a trailing dot, e.g. "J.S.". */
    static String initials(Owner owner) {
        return (owner.getFirstName().substring(0, 1) + "." + owner.getLastName().substring(0, 1) + ".")
                .toUpperCase();
    }

    /**
     * The sequential membership number for the owner: one more than the number of owners that existed
     * before this one. Computed as the count of owners whose id is not greater than this owner's id.
     * Because a newly created owner always has the largest id, this equals the total owner count at
     * registration and stays stable when read back later.
     */
    static Integer membershipNumber(Owner owner, Collection<Owner> allOwners) {
        Integer id = owner.getId();
        if (id == null) {
            return null;
        }
        return (int) allOwners.stream()
                .filter(o -> o.getId() != null && o.getId() <= id)
                .count();
    }

    /**
     * The per-city customer code for the owner, formatted {@code "<UPPERCASE_CITY>-<NNNN>"} where NNNN
     * is one more than the number of owners already in that city, zero-padded to four digits (e.g.
     * "LONDON-0007"). Computed as the count of owners in the same city (case-insensitive) whose id is
     * not greater than this owner's id. Because a newly created owner always has the largest id, this
     * equals the number already in that city plus one at registration and stays stable when read back
     * later.
     */
    static String customerCode(Owner owner, Collection<Owner> allOwners) {
        Integer id = owner.getId();
        String city = owner.getCity();
        if (id == null || city == null) {
            return null;
        }
        long sequence = allOwners.stream()
                .filter(o -> o.getId() != null && o.getId() <= id && city.equalsIgnoreCase(o.getCity()))
                .count();
        return String.format("%s-%04d", city.toUpperCase(), sequence);
    }

    /**
     * The membership tier assigned to the owner at registration: {@code "FOUNDING"} for the first 100
     * owners ever created and {@code "STANDARD"} for all later owners. Derived from the sequential
     * {@link #membershipNumber(Owner, Collection) membership number}, so it is stable when read back later.
     */
    static String membershipTier(Owner owner, Collection<Owner> allOwners) {
        Integer number = membershipNumber(owner, allOwners);
        if (number == null) {
            return null;
        }
        return number <= 100 ? "FOUNDING" : "STANDARD";
    }

    /**
     * The number of other owners that shared this owner's last name at the moment of registration.
     * Computed as the count of owners, excluding this one, whose id is smaller than this owner's id and
     * whose last name matches (case-insensitively). Because a newly created owner always has the largest
     * id, this equals the number of existing namesakes at registration and stays stable when read back later.
     */
    static Integer namesakeCount(Owner owner, Collection<Owner> allOwners) {
        Integer id = owner.getId();
        String lastName = owner.getLastName();
        if (id == null || lastName == null) {
            return null;
        }
        return (int) allOwners.stream()
                .filter(o -> o.getId() != null && o.getId() < id && lastName.equalsIgnoreCase(o.getLastName()))
                .count();
    }

    /**
     * Whether, at registration, another owner already had the same address and city. Computed as
     * whether any owner with a smaller id shares this owner's address and city (both matched
     * case-insensitively). Because a newly created owner always has the largest id, this reflects the
     * owners that existed before this one and stays stable when read back later.
     */
    static Boolean sharesHousehold(Owner owner, Collection<Owner> allOwners) {
        Integer id = owner.getId();
        String address = owner.getAddress();
        String city = owner.getCity();
        if (id == null || address == null || city == null) {
            return false;
        }
        return allOwners.stream()
                .anyMatch(o -> o.getId() != null && o.getId() < id
                        && address.equalsIgnoreCase(o.getAddress())
                        && city.equalsIgnoreCase(o.getCity()));
    }

    /**
     * The locality classification assigned to the owner at registration: {@code "local"} when this
     * owner's city is the single most common city among the owners that existed at registration, and
     * {@code "remote"} otherwise. The population considered is the owners whose id is not greater than
     * this owner's id (cities matched case-insensitively); because a newly created owner always has the
     * largest id, this reflects the owners present at registration and stays stable when read back later.
     * A tie for the most common city yields {@code "remote"}, since there is then no single most common city.
     */
    static String locality(Owner owner, Collection<Owner> allOwners) {
        Integer id = owner.getId();
        String city = owner.getCity();
        if (id == null || city == null) {
            return null;
        }
        String cityKey = city.toLowerCase();
        java.util.Map<String, Long> counts = allOwners.stream()
                .filter(o -> o.getId() != null && o.getId() <= id && o.getCity() != null)
                .collect(java.util.stream.Collectors.groupingBy(o -> o.getCity().toLowerCase(),
                        java.util.stream.Collectors.counting()));
        long ownerCityCount = counts.getOrDefault(cityKey, 0L);
        boolean singleMostCommon = counts.entrySet().stream()
                .noneMatch(e -> !e.getKey().equals(cityKey) && e.getValue() >= ownerCityCount);
        return singleMostCommon ? "local" : "remote";
    }

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

